import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate, useNavigate } from "react-router-dom";
import Splash from "./Splash";
import LoginScreen from "./Login";
import AdminLogin from "./AdminLogin";
import Dashboard from "./Dashboard";
import AdminDashboard from "./AdminDashboard";
import ReportsDashboard from "./ReportsDashboard";
import ProbarModelo from "./ProbarModelo";

export default function App() {
  const [role, setRole] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Funciones de navegación y autenticación
  const handleSplashDone = (navigate) => {
    navigate("/login");
  };
  const handleLoginSelect = (sel, navigate) => {
    if (sel === "admin") {
      navigate("/adminLogin");
    } else {
      setRole("user");
      setIsAuthenticated(true);
      navigate("/dashboard");
    }
  };
  const handleAdminSubmit = (navigate) => {
    setRole("admin");
    setIsAuthenticated(true);
    navigate("/dashboard");
  };
  const handleLogout = (navigate) => {
    setRole(null);
    setIsAuthenticated(false);
    navigate("/login");
  };

  // Para ProbarModelo desde login
  const handleProbarModelo = (navigate) => {
    setRole("user");
    setIsAuthenticated(true);
    navigate("/probarModelo");
  };

  // Componente wrapper para pasar navigate a los hijos
  function WithNavigate(Component, extraProps = {}) {
    return (props) => {
      const navigate = useNavigate();
      return <Component {...props} {...extraProps} navigate={navigate} />;
    };
  }

  return (
    <Router>
      <Routes>
        <Route path="/splash" element={<WithNavigate Component={Splash} onDone={handleSplashDone} />} />
        <Route path="/login" element={<WithNavigate Component={LoginScreen} onSelect={handleLoginSelect} onProbarModelo={handleProbarModelo} />} />
        <Route path="/adminLogin" element={<WithNavigate Component={AdminLogin} onBack={handleLogout} onLogin={handleAdminSubmit} />} />
        <Route path="/dashboard" element={isAuthenticated ? <Dashboard onBack={handleLogout} /> : <Navigate to="/login" />} />
        <Route path="/adminDashboard" element={isAuthenticated && role === "admin" ? <AdminDashboard onHome={handleLogout} onReports={() => {}} /> : <Navigate to="/login" />} />
        <Route path="/reports" element={isAuthenticated && role === "admin" ? <ReportsDashboard onBack={() => {}} /> : <Navigate to="/login" />} />
        <Route path="/probarModelo" element={isAuthenticated ? <ProbarModelo /> : <Navigate to="/login" />} />
        <Route path="*" element={<Navigate to="/splash" />} />
      </Routes>
    </Router>
  );
}
